//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF05240.xml";
scwin.gDepCd;
scwin.gEmpNo;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();
};
scwin.fn_list_sync_1 = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=SKIL_GRWTH_COM_GRACE_INOUT&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&SCREN_ID=" + scwin.vScrenID + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.kosdaq.select.skil_grwth_com_gracepd" + "&{P}V_ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&{P}V_DEP_CD=" + $c.stf.getObjectValue(cmb_DEP_CD) + "&{P}V_EMP_NO=" + $c.stf.getObjectValue(cmb_EMP_NO);
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
    $c.cm.ShowWin(grd_Grid1);
};
scwin.fn_list_sync_2 = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=SKIL_GRWTH_COM_GRACE_INOUT&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&SCREN_ID=" + scwin.vScrenID + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.kosdaq.select.nrealz_proft_gracepd" + "&{P}V_ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&{P}V_DEP_CD=" + $c.stf.getObjectValue(cmb_DEP_CD) + "&{P}V_EMP_NO=" + $c.stf.getObjectValue(cmb_EMP_NO);
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
    $c.cm.ShowWin(grd_Grid2);
};
scwin.showPanCnd = function(idx) {
    //	pan_cnd.style.display = (idx == 1 ? "none" :  "");

};
scwin.fn_setPara = function(obj) {
    gIsurCd = dts_List.getCellData(obj, "ISUR_CD");
};
scwin.fn_getParaIsurCd = function() {
    return gIsurCd;
};
scwin.fn_save = function() {
    var gCnt = 0;
    for (var k = 1; k <= dts_Grid.getTotalRow(); k++) {
        gStat = dts_Grid.getRowStatus(k);
        if (gStat == TB_JOB_UPDATE) {
            if (dts_Grid.getCellData(k, "DEP_CD") == js_dep_cd) {
                dts_Grid.setCellData(k, "ADJPRN_EMP_NO", js_emp_no);
                gCnt++;
            } else {
                $c.win.alert(k + "번째 " + dts_Grid.getCellData(k, "COM_ABBRV") + "항목은 해당팀만 수정할 수 있습니다.");
                return;
            }
        }
    }
    if (gCnt == 0) {
        $c.win.alert("수정할 내용이 없습니다.");
        return;
    }
    if (window.confirm(gCnt + "건 수정 하시겠습니까?")) {
        var url = "/SkillGrwComGrace.do?method=insertSkillGrwComGrace&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_save.Action = url;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_Grid)";
        trs_save.Post();
    }
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    if (rowcount <= 0) {
        dts_Grid.removeAll();
    }
    if (MxTab_1.getSelectedTabIndex() == 1) {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
        $c.cm.CloseWin(rowcount, grd_Grid1);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
        $c.cm.CloseWin(rowcount, grd_Grid2);
    }
};
scwin.MxTab_1_PreSelChangeNotify = function(nIndex) {
    /*	if (nIndex == 1) {
    		fn_list_sync_1();
    	} else if (nIndex == 2) {
    		fn_list_sync_2();
    	}*/
};
scwin.btn_toexcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀
    if (MxTab_1.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_Grid1, "기술성장기업", "", "8");
    } else {
        $c.data.downloadGridViewExcel(grd_Grid2, "이익미실현기업", "", "8");
    }
};
scwin.btn_select_onclick = function() {
    if (MxTab_1.getSelectedTabIndex() == 1) {
        scwin.fn_list_sync_1();
    } else if (MxTab_1.getSelectedTabIndex() == 2) {
        scwin.fn_list_sync_2();
    }
};
scwin.btn_close_onclick = function() {
    self.close();
};
scwin.MxTab_1_OnSelChanged = function(nIndex) {
    //showPanCnd(nIndex);
    if (nIndex == 1) {
        scwin.fn_list_sync_1();
    } else if (nIndex == 2) {
        scwin.fn_list_sync_2();
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_DEP_CD, "VALUE", cmb_DEP_CD.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_EMP_NO, '');
    }
    dts_emp.UseFilter = true;
    dts_emp.Filter();
    dts_emp.sort("DEP_CD", 0);
    //dts_emp.sort(); // W-Craft 주석처리 

};
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.dts_emp_OnLoadError = function() {
    $c.stf.alert_error(dts_emp);
};
scwin.dts_dep_OnLoadError = function() {
    $c.stf.alert_error(dts_dep);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    grd_Grid1.ActiveIndex = 1;
    scwin.showPanCnd(MxTab_1.getSelectedTabIndex());
    scwin.fn_SetCode();
    scwin.fn_list_sync_1();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    scwin.fn_setPara(row);
    var wth = 580;
    var hgt = 220;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("gform", "/lstproc/ULDSTF05245.gfm", "영업손실 유예 관리", pt.x, pt.y, wth, hgt, "window");

    //fn_list_sync();

};
scwin.btn_Search_onclick = function() {
    fn_list_sync();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    fn_list_sync();
};
scwin.txb_ISUR_CD_onblur = function() {
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.btn_cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Excel_onclick = function() {
    // 엑셀
    if (nIndex == 1) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid1, "기술성장기업", "", "8");
    } else if (nIndex == 2) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid2, "이익미실현기업", "", "8");
    }
};
scwin.btn_Modify_onclick = function() {
    scwin.fn_save();
};
scwin.trs_save_OnSuccess = function() {
    //fn_listNewsflashFinance();
    $c.win.alert("저장 되었습니다.");
};
